before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <algorithm>
#include <iostream>
#include <vector>
int main() {
    std::vector<int> values{3, 1, 2};
    std::sort(values.begin(), values.end(), [](int a, int b) { return a > b; });
    for (int value : values) std::cout << value << ' ';
    std::cout << '\n';
}

```

